CREATE FUNCTION public.fin_billing_plan_queue() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb:='[]';p record;plan jsonb;r jsonb;BEGIN IF NOT public.fin_invoice_queue_access() THEN RAISE EXCEPTION 'Finance access required' USING ERRCODE='42501';END IF;FOR p IN SELECT id,name,company_id FROM pm_projects WHERE public.pm_payment_finance_access(id) AND public.can_view_project_area(id,'financials') LOOP plan:=public.pm_billing_plan(p.id);FOR r IN SELECT value FROM jsonb_array_elements(plan->'rows') WHERE value->>'direction'='inflow' LOOP result:=result||jsonb_build_array(r||jsonb_build_object('project_name',p.name,'client_name',(SELECT nome FROM companies WHERE id=p.company_id),'pm_date_moves',0,'project_stages',plan->'stages'));END LOOP;END LOOP;RETURN jsonb_build_object('rows',result,'today',(now() AT TIME ZONE 'Europe/Lisbon')::date,'can_issue',true);END $$;
REVOKE ALL ON FUNCTION public.fin_billing_plan_queue() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.fin_billing_plan_queue() TO authenticated;
DO $$ DECLARE d text;BEGIN SELECT pg_get_functiondef('public.pm_invoice_regroup(text,uuid)'::regprocedure) INTO d;d:=replace(d,$a$AND coalesce(payment_terms,'') !~*$a$, $b$AND ($2<>'pm_payment_schedule_items' OR id NOT IN(SELECT id FROM public.pm_payment_schedule_items WHERE manual_billing_group_id IS NOT NULL)) AND coalesce(payment_terms,'') !~*$b$);d:=replace(d,'USING _scope LOOP','USING _scope,_tbl LOOP');EXECUTE d;END $$;
CREATE FUNCTION public.pm_billing_update_group(_group uuid,_description text,_date date) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE g pm_billing_groups;p pm_payment_schedule_items;BEGIN SELECT * INTO g FROM pm_billing_groups WHERE id=_group AND dissolved_at IS NULL FOR UPDATE;IF g.id IS NULL OR NOT public.pm_can_edit_gantt(g.project_id) THEN RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501';END IF;IF length(trim(coalesce(_description,''))) NOT BETWEEN 1 AND 4000 THEN RAISE EXCEPTION 'Invoice description required';END IF;FOR p IN SELECT * FROM pm_payment_schedule_items WHERE manual_billing_group_id=g.id ORDER BY id FOR UPDATE LOOP IF public.pm_billing_item_protected(p.id) THEN RAISE EXCEPTION 'Issued groups are locked';END IF;END LOOP;UPDATE pm_billing_groups SET description=trim(_description),planned_date_override=_date WHERE id=g.id;UPDATE pm_invoice_readiness SET confirmed_at=NULL WHERE payment_item_id IN(SELECT id FROM pm_payment_schedule_items WHERE manual_billing_group_id=g.id);INSERT INTO pm_invoice_workflow_audit(project_id,payment_item_id,actor,action,before_values,after_values) SELECT g.project_id,id,auth.uid(),'group_description_date',to_jsonb(g),jsonb_build_object('description',trim(_description),'date',_date) FROM pm_payment_schedule_items WHERE manual_billing_group_id=g.id;END $$;
REVOKE ALL ON FUNCTION public.pm_billing_update_group(uuid,text,date) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.pm_billing_update_group(uuid,text,date) TO authenticated;